--
-- Table structure for table `engineering_process_icon_sample`
--

DROP TABLE IF EXISTS `engineering_process_icon_sample`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_process_icon_sample` (
  `sample_id` bigint NOT NULL AUTO_INCREMENT COMMENT '工序图标样本ID',
  `process_id` bigint DEFAULT NULL COMMENT '标准工序ID，未确认时可空',
  `archive_id` bigint DEFAULT NULL COMMENT '来源历史档案ID',
  `workflow_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PANEL/UP_LINE/DOWN_LINE',
  `step_no` int DEFAULT NULL COMMENT '来源区域内序号',
  `original_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始裁剪图路径',
  `normalized_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准化识别图路径',
  `perceptual_hash` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '64位感知哈希',
  `match_score` decimal(6,5) DEFAULT NULL COMMENT '自动匹配相似度',
  `confirm_status` tinyint NOT NULL DEFAULT '0' COMMENT '0待确认 1已确认 2已忽略',
  `usage_count` int NOT NULL DEFAULT '0' COMMENT '命中次数',
  `use_as_system_icon` tinyint NOT NULL DEFAULT '0' COMMENT '是否延用为系统展示图标',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `parent_sample_id` bigint DEFAULT NULL COMMENT '复合父样本ID，普通样本为空',
  `component_order` int DEFAULT NULL COMMENT '复合子项顺序',
  `work_instruction` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '子工序作业说明/下标',
  PRIMARY KEY (`sample_id`),
  KEY `idx_icon_process_confirm` (`process_id`,`confirm_status`),
  KEY `idx_icon_hash` (`perceptual_hash`),
  KEY `idx_icon_archive` (`archive_id`),
  KEY `idx_icon_parent_component` (`parent_sample_id`,`component_order`),
  KEY `idx_icon_workflow_hash_process` (`workflow_type`,`perceptual_hash`,`process_id`,`confirm_status`),
  CONSTRAINT `fk_icon_sample_archive` FOREIGN KEY (`archive_id`) REFERENCES `engineering_archive_import` (`archive_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_icon_sample_process` FOREIGN KEY (`process_id`) REFERENCES `engineering_standard_process` (`process_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11747 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='历史档案工序图标识别样本';
/*!40101 SET character_set_client = @saved_cs_client */;

