DROP TABLE IF EXISTS `engineering_resource_maintenance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_resource_maintenance` (
  `maintenance_id` bigint NOT NULL AUTO_INCREMENT,
  `resource_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SCREEN_FRAME/SCREEN_PLATE/DIE',
  `resource_id` bigint NOT NULL,
  `action_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PLATE/WASH/REPAIR/REMAKE/STOP/ENABLE/SCRAP',
  `before_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `after_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `successor_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '重做后的资源类型',
  `successor_id` bigint DEFAULT NULL COMMENT '重做后的资源ID',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`maintenance_id`),
  KEY `idx_resource_maintenance_resource` (`resource_type`,`resource_id`,`operate_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工程资源维护履历';
