--
-- Table structure for table `engineering_screen_plate`
--

DROP TABLE IF EXISTS `engineering_screen_plate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_screen_plate` (
  `plate_id` bigint NOT NULL AUTO_INCREMENT COMMENT '制版履历ID',
  `frame_id` bigint NOT NULL COMMENT '网框实体ID',
  `plate_no` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版面编号',
  `film_id` bigint DEFAULT NULL COMMENT '来源菲林ID',
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版面内容',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE有效/WASHED已洗版/VOID作废',
  `plated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '制版时间',
  `washed_time` datetime DEFAULT NULL COMMENT '洗版时间',
  `end_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结束原因',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`plate_id`),
  UNIQUE KEY `uk_screen_plate_no` (`plate_no`),
  KEY `idx_screen_plate_frame_status` (`frame_id`,`status`),
  KEY `idx_screen_plate_film` (`film_id`),
  CONSTRAINT `fk_screen_plate_film` FOREIGN KEY (`film_id`) REFERENCES `engineering_film` (`film_id`),
  CONSTRAINT `fk_screen_plate_frame` FOREIGN KEY (`frame_id`) REFERENCES `engineering_screen_frame` (`frame_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工程-网版制版履历';
/*!40101 SET character_set_client = @saved_cs_client */;

