--
-- Table structure for table `sales_customer`
--

DROP TABLE IF EXISTS `sales_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_customer` (
  `customer_id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户ID',
  `customer_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `customer_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `customer_short_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户简称',
  `customer_type` tinyint DEFAULT '1' COMMENT '客户类型 (1: 终端客户, 2: 代理商, 3: 经销商)',
  `customer_level` tinyint DEFAULT '2' COMMENT '客户等级 (1: A级, 2: B级, 3: C级)',
  `industry_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业分类',
  `customer_source` tinyint DEFAULT '1' COMMENT '客户来源 (1: 展会, 2: 网络, 3: 转介绍, 4: 主动开发)',
  `country` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省份',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细地址',
  `postal_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮政编码',
  `contact_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `fax` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '传真',
  `website` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网址',
  `unified_social_credit_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '统一社会信用代码',
  `taxpayer_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人识别号',
  `bank_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账号',
  `payment_method` tinyint DEFAULT '1' COMMENT '付款方式 (1: 预付, 2: 货到付款, 3: 月结30天, 4: 月结60天)',
  `payment_terms` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '付款条件',
  `payment_term_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账期类型：PREPAID/COD/NET_DAYS/MONTH_END',
  `credit_days` int DEFAULT NULL COMMENT '账期天数',
  `credit_start_basis` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CUSTOMER_RECEIPT_DATE' COMMENT '账期起算基准',
  `credit_limit` decimal(15,2) DEFAULT '0.00' COMMENT '信用额度',
  `used_credit_limit` decimal(15,2) DEFAULT '0.00' COMMENT '已用信用额度',
  `customer_status` tinyint DEFAULT '1' COMMENT '客户状态 (1: 潜在客户, 2: 正式客户, 3: 暂停合作, 4: 终止合作)',
  `cooperation_start_date` datetime DEFAULT NULL COMMENT '合作开始日期',
  `cooperation_end_date` datetime DEFAULT NULL COMMENT '合作结束日期',
  `sales_manager_id` bigint DEFAULT NULL COMMENT '销售负责人ID',
  `sales_manager_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售负责人姓名',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '客户备注',
  `customer_score` tinyint DEFAULT '3' COMMENT '客户评分 (1-5分)',
  `annual_purchase_amount` decimal(15,2) DEFAULT '0.00' COMMENT '年采购额',
  `main_product_demand` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要产品需求',
  `special_requirements` text COLLATE utf8mb4_unicode_ci COMMENT '特殊要求',
  `is_vip` tinyint(1) DEFAULT '0' COMMENT '是否VIP客户',
  `customer_tags` json DEFAULT NULL COMMENT '客户标签 (JSON格式存储多个标签)',
  `attachments` json DEFAULT NULL COMMENT '附件信息 (JSON格式存储附件信息)',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '删除标志 (0: 正常, 1: 删除)',
  PRIMARY KEY (`customer_id`),
  UNIQUE KEY `uk_customer_code` (`customer_code`),
  KEY `idx_customer_name` (`customer_name`),
  KEY `idx_customer_status` (`customer_status`),
  KEY `idx_sales_manager_id` (`sales_manager_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售客户表';
/*!40101 SET character_set_client = @saved_cs_client */;

