DROP TABLE IF EXISTS `sales_delivery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_delivery` (
  `delivery_id` bigint NOT NULL AUTO_INCREMENT COMMENT '发货单ID',
  `delivery_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发货单号',
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `customer_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `delivery_date` date NOT NULL COMMENT '发货日期',
  `delivery_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发货地址',
  `contact_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `delivery_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发货方式',
  `tracking_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流单号',
  `carrier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承运商',
  `delivery_status` tinyint DEFAULT '1' COMMENT '发货状态 (1: 待发货, 2: 已发货, 3: 已签收, 4: 异常)',
  `total_quantity` int DEFAULT '0' COMMENT '总数量',
  `total_weight` decimal(10,2) DEFAULT '0.00' COMMENT '总重量',
  `total_volume` decimal(10,2) DEFAULT '0.00' COMMENT '总体积',
  `freight_amount` decimal(15,2) DEFAULT '0.00' COMMENT '运费金额',
  `insurance_amount` decimal(15,2) DEFAULT '0.00' COMMENT '保险费',
  `other_charges` decimal(15,2) DEFAULT '0.00' COMMENT '其他费用',
  `total_amount` decimal(15,2) DEFAULT '0.00' COMMENT '总金额',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `delivery_person_id` bigint DEFAULT NULL COMMENT '发货人ID',
  `delivery_person_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发货人姓名',
  `receiver_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收货人电话',
  `receive_time` datetime DEFAULT NULL COMMENT '签收时间',
  `customer_receive_date` date DEFAULT NULL COMMENT '客户签收日期（纸面，口径D1）',
  `receive_remark` text COLLATE utf8mb4_unicode_ci COMMENT '签收备注',
  `receive_by` bigint DEFAULT NULL COMMENT '签收操作人ID',
  `receive_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签收操作人姓名',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '删除标志 (0: 正常, 1: 删除)',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拒收原因',
  `reject_time` datetime DEFAULT NULL COMMENT '拒收登记时间',
  `reject_by` bigint DEFAULT NULL COMMENT '拒收登记人ID',
  `reject_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拒收登记人',
  PRIMARY KEY (`delivery_id`),
  UNIQUE KEY `uk_delivery_no` (`delivery_no`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_delivery_date` (`delivery_date`),
  KEY `idx_delivery_status` (`delivery_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售发货单表';
