--
-- Table structure for table `sys_error_log`
--

DROP TABLE IF EXISTS `sys_error_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_error_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trace_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '追踪ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `username` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户账号',
  `exception_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常类名',
  `exception_msg` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常消息',
  `request_url` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求URL',
  `request_method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求方式',
  `request_params` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求参数',
  `client_ip` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端IP',
  `trigger_time` datetime DEFAULT NULL COMMENT '触发时间',
  `handle_status` tinyint DEFAULT '0' COMMENT '处理状态(0未处理 1已处理 2已忽略)',
  `handle_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理备注',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理人',
  PRIMARY KEY (`id`),
  KEY `idx_trace_id` (`trace_id`),
  KEY `idx_exception_name` (`exception_name`),
  KEY `idx_trigger_time` (`trigger_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='错误日志表(精简版)';
/*!40101 SET character_set_client = @saved_cs_client */;

