--
-- Table structure for table `sys_event_config`
--

DROP TABLE IF EXISTS `sys_event_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_event_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `biz_module` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `event_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'notification/task/both',
  `kanban_module` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'office' COMMENT '看板模块: office/emergency/production/dev',
  `priority` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT '任务优先级: urgent/high/normal/low',
  `is_enabled` tinyint(1) DEFAULT '1',
  `target_role` json DEFAULT NULL COMMENT '角色ID列表: [7, 8]',
  `title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `exclude_trigger` tinyint(1) DEFAULT '0' COMMENT '排除触发者',
  `close_source_events` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发时关闭的source_event(逗号分隔,同biz_id的office待办任务)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `event_code` (`event_code`)
) ENGINE=InnoDB AUTO_INCREMENT=187 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

