--
-- Table structure for table `sys_oper_log`
--

DROP TABLE IF EXISTS `sys_oper_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `username` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人账号',
  `real_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `tenant_id` bigint DEFAULT '1' COMMENT '租户ID',
  `module` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作模块',
  `business_type` bigint NOT NULL DEFAULT '1' COMMENT '业务类型',
  `biz_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型：ORDER/PRODUCT/BOM/ROUTING/INVENTORY',
  `biz_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务ID：订单号/产品ID/BOM_ID等',
  `trace_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '追踪ID，贯穿整笔请求',
  `biz_status` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务状态值（各模块自定义，可为状态码或语义值）',
  `oper_url` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求URL',
  `oper_ip` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作IP',
  `oper_param` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '请求参数（原 varchar(2000) 超长会丢日志，2026-09-21 dev-20260921-003 扩容）',
  `detail` json DEFAULT NULL COMMENT '操作详情（JSON格式）',
  `cost_time` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `status` tinyint DEFAULT '1' COMMENT '状态(0失败 1成功)',
  `error_msg` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `user_agent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '浏览器UA',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `action` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作动作中文文案（如 执行预警检查）',
  PRIMARY KEY (`id`),
  KEY `idx_user_time` (`user_id`,`create_time`),
  KEY `idx_module_time` (`module`,`create_time`),
  KEY `idx_biz` (`biz_type`,`biz_id`,`create_time`),
  KEY `idx_trace` (`trace_id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作日志表';
